import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

@DisplayName("70/67_lru_cache")
class SolutionTest {

    @Test
    void shouldFollowStandardLruSequence() {

        Completed cache = new Completed(2);

        cache.put(1, 1);
        cache.put(2, 2);

        assertEquals(1, cache.get(1));

        cache.put(3, 3);

        assertEquals(-1, cache.get(2));

        cache.put(4, 4);

        assertEquals(-1, cache.get(1));
        assertEquals(3, cache.get(3));
        assertEquals(4, cache.get(4));
    }

    @Test
    void shouldUpdateExistingKeyWithoutEviction() {

        Completed cache = new Completed(2);

        cache.put(1, 1);
        cache.put(2, 2);
        cache.put(1, 10);

        assertEquals(10, cache.get(1));
        assertEquals(2, cache.get(2));
    }

    @Test
    void shouldEvictLeastRecentlyUsedAfterGet() {

        Completed cache = new Completed(2);

        cache.put(1, 1);
        cache.put(2, 2);
        cache.get(1);
        cache.put(3, 3);

        assertEquals(1, cache.get(1));
        assertEquals(-1, cache.get(2));
        assertEquals(3, cache.get(3));
    }

    @Test
    void shouldReturnMinusOneForMissingKey() {

        Completed cache = new Completed(1);

        assertEquals(-1, cache.get(5));

        cache.put(5, 50);

        assertEquals(50, cache.get(5));
    }

    @Test
    void shouldEvictImmediatelyWhenCapacityIsOne() {

        Completed cache = new Completed(1);

        cache.put(1, 1);
        cache.put(2, 2);

        assertEquals(-1, cache.get(1));
        assertEquals(2, cache.get(2));
    }
}
